  function render() {
    tabs.forEach(function (t) {
      var on = Number(t.dataset.stepBtn) === step;
      t.classList.toggle('is-active', on);
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
    });
    panes.forEach(function (p) {
      p.classList.toggle('is-active', Number(p.dataset.stepPane) === step);
    });
    btnPrev.disabled = step === 0;
    btnNext.hidden = step === STEPS - 1;
    btnFinish.hidden = step !== STEPS - 1;
    if (progressEl) progressEl.style.width = ((step + 1) / STEPS * 100) + '%';
    if (wizardBody) wizardBody.dataset.step = String(step);
    centerActiveTab();
  }

  function setStep(n) {
    var next = Math.max(0, Math.min(STEPS - 1, n));
    if (next === step) return;
    step = next;
    render();
  }

  function centerActiveTab() {
    if (!tabsWrap || tabsWrap.scrollWidth <= tabsWrap.clientWidth + 1) return;
    var active = tabs.filter(function (t) { return Number(t.dataset.stepBtn) === step; })[0];
    if (!active) return;
    var cRect = tabsWrap.getBoundingClientRect();
    var tRect = active.getBoundingClientRect();
    var target = tabsWrap.scrollLeft + (tRect.left - cRect.left) + tRect.width / 2 - tabsWrap.clientWidth / 2;
    var max = Math.max(0, tabsWrap.scrollWidth - tabsWrap.clientWidth);
    var clamped = Math.max(0, Math.min(target, max));
    if (Math.abs(tabsWrap.scrollLeft - clamped) < 2) return;
    if (tabsWrap.scrollTo) {
      try { tabsWrap.scrollTo({ left: clamped, behavior: 'smooth' }); return; } catch (e) {}
    }
    tabsWrap.scrollLeft = clamped;
  }

  /* ---------- открытие / закрытие модалки ---------- */
  function lockScroll(on) {
    document.documentElement.classList.toggle('no-scroll', on);
    document.body.classList.toggle('no-scroll', on);
  }

  function openWizard() {
    lastFocused = document.activeElement;
    wizard.classList.add('is-open');
    wizard.setAttribute('aria-hidden', 'false');
    lockScroll(true);
    render();
    if (wizardBody) wizardBody.scrollTop = 0;
    var closeBtn = $('.disc-modal__close', wizard);
    if (closeBtn) { try { closeBtn.focus({ preventScroll: true }); } catch (e) { closeBtn.focus(); } }
    centerActiveTab();
  }

  function closeWizard() {
    wizard.classList.remove('is-open');
    wizard.setAttribute('aria-hidden', 'true');
    lockScroll(false);
    if (lastFocused && typeof lastFocused.focus === 'function' && document.contains(lastFocused)) {
      try { lastFocused.focus({ preventScroll: true }); } catch (e) { lastFocused.focus(); }
    }
    lastFocused = null;
  }

  function wizardOpen() { return wizard.classList.contains('is-open'); }

  /* ---------- подсчёт результата (как в оригинале:
       позиция 0 списка — «major», позиция 3 — «minor») ---------- */
  function collect() {
    var maj = { d: 0, i: 0, s: 0, c: 0 };
    var min = { d: 0, i: 0, s: 0, c: 0 };
    lists.forEach(function (ul) {
      var lis = ul.children;
      if (lis.length < 4) return;
      var top = lis[0].getAttribute('data-type');
      var bottom = lis[3].getAttribute('data-type');
      if (top in maj) maj[top] += 1;
      if (bottom in min) min[bottom] += 1;
    });
    return {
      d: maj.d - min.d,
      i: maj.i - min.i,
      s: maj.s - min.s,
      c: maj.c - min.c
    };
  }

  function formatScore(sc) {
    return 'D:' + sc.d + ', I:' + sc.i + ', S:' + sc.s + ', C:' + sc.c;
  }

  /* ---------- результат на том же экране ---------- */
  function showResult(sc) {
    lastScoreStr = formatScore(sc);
    var strEl = $('#scoreString');
    if (strEl) {
      strEl.innerHTML = '';
      ['d', 'i', 's', 'c'].forEach(function (k, idx) {
        if (idx > 0) strEl.appendChild(document.createTextNode(', '));
        var s = document.createElement('span');
        s.textContent = k.toUpperCase() + ':' + sc[k];
        strEl.appendChild(s);
      });
    }

    var max = Math.max(1, Math.abs(sc.d), Math.abs(sc.i), Math.abs(sc.s), Math.abs(sc.c));
    ['d', 'i', 's', 'c'].forEach(function (k) {
      var fill = $('.bar__fill--' + k);
      var val = $('.bar__value[data-type="' + k + '"]');
      var v = sc[k];
      if (fill) {
        fill.style.width = (Math.abs(v) / max * 50) + '%';
        fill.style.left = v >= 0 ? '50%' : 'auto';
        fill.style.right = v < 0 ? '50%' : 'auto';
      }
      if (val) val.textContent = String(v);
    });

    startScreen.hidden = true;
    resultScreen.hidden = false;
    window.scrollTo(0, 0);
    var title = $('#resultTitle');
    if (title) { try { title.focus({ preventScroll: true }); } catch (e) { title.focus(); } }
  }

  function resetLists() {
    lists.forEach(function (ul, i) {
      initialOrder[i].forEach(function (li) { ul.appendChild(li); });
    });
  }

  /* ---------- перетаскивание (Pointer Events, без библиотек) ---------- */
  var drag = null; /* {li, ul, id, startX, startY, offX, offY, x, y, active, ghost, raf} */

  function isCoarsePointer() {
    return window.matchMedia && window.matchMedia('(pointer: coarse)').matches;
  }

  function onPointerDown(e) {
    if (drag) return;
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    var li = e.target && e.target.closest ? e.target.closest('.disc-item') : null;
    if (!li || lists.indexOf(li.parentElement) === -1) return;
    /* на тач-устройствах перетаскивание только за «точки» (как в оригинале) */
    if (isCoarsePointer() && !e.target.closest('.disc-handle')) return;

    var rect = li.getBoundingClientRect();
    drag = {
      li: li,
      ul: li.parentElement,
      id: e.pointerId,
      startX: e.clientX,
      startY: e.clientY,
      offX: e.clientX - rect.left,
      offY: e.clientY - rect.top,
      x: e.clientX,
      y: e.clientY,
      active: false,
      ghost: null,
      raf: 0
    };
    window.addEventListener('pointermove', onPointerMove, { passive: false });
    window.addEventListener('pointerup', onPointerUp);
    window.addEventListener('pointercancel', onPointerUp);
